// ФОРМА ОБВЯЗКИ К БРАУЗЕРУ — объявлена здесь, и это НАЗВАННЫЙ ПРОБЕЛ, а не решение.
//
// `@omnifield/live-check` — пакет воркспейса без деклараций: он написан на `.mjs`, типов наружу
// не отдаёт, и компилятор видит его как `any`. Молча оставить `any` нельзя — тогда опечатка в
// имени функции доехала бы до прогона браузера и выглядела бы как поломка замера.
//
// Правильно было бы, чтобы форму объявляла та зона, что владеет обвязкой. Здесь она записана
// ВТОРОЙ КОПИЕЙ — ровно того же рода, что копии чужих имён у механики скина: если обвязка сменит
// сигнатуру, компилятор здесь этого не заметит. Заявка поднята архитектору.
//
// Объявлено УЗКО — только то, чем пользуется гейт совпадения. Полная копия чужой поверхности
// расходилась бы с оригиналом быстрее и незаметнее.

declare module "@omnifield/live-check" {
  /** Дескриптор канала к браузеру: зовёт метод протокола и отдаёт ответ. */
  export type Call = (method: string, params?: Record<string, unknown>) => Promise<unknown>;

  /** Поднимает браузер, отдаёт канал и гасит его после — что бы ни случилось внутри. */
  export function withChrome<T>(run: (call: Call) => Promise<T>): Promise<T>;

  /** Загружает страницу текстом и ждёт, пока документ соберётся. */
  export function load(call: Call, html: string): Promise<void>;

  /** Спрашивает страницу выражением и отдаёт значение. */
  export function ask(call: Call, expression: string): Promise<string>;
}
